/**
 * §15 Axis 2 Bar #2 — empirical verification of the má/mã spec.
 *
 * Answers dispatch question 2: "If Azure can't empirically distinguish
 * má (sắc) from mã (ngã), STOP — design pivots to Option B (Web Audio
 * local pitch extractor)." This is the merge gate the owner enforces.
 *
 * What it does:
 *   1. Reads the prerecorded má.mp3 and mã.mp3 fixtures (the same
 *      audio the drill UI plays back to learners). These were
 *      generated by `scripts/generate-tone-references.ts`.
 *   2. Calls the `azure-phoneme` edge function four times:
 *        a. má.mp3 targeted at má  (matched)   → expected: pass
 *        b. má.mp3 targeted at mã  (mismatched)→ expected: retry
 *        c. mã.mp3 targeted at mã  (matched)   → expected: pass
 *        d. mã.mp3 targeted at má  (mismatched)→ expected: retry
 *   3. Prints the score + bucket for each call.
 *   4. Tristate exit (PRINCIPLES #7 — "unavailable" is NOT "Azure
 *      failed"):
 *        0  VERIFIED PASS  All 4 calls returned a real Azure score
 *                          AND ordering is correct (matched ≥
 *                          low-confidence-pass, mismatched = retry).
 *                          Bar #2 unblocked — Option A confirmed.
 *        2  VERIFIED FAIL  All 4 calls returned real Azure scores
 *                          AND ordering is wrong (Azure cannot
 *                          empirically distinguish má vs mã).
 *                          Escalate to design §5 Option B (Web Audio
 *                          local pitch extractor).
 *        3  INCONCLUSIVE   Any call returned `unavailable`. The
 *                          request never reached Azure scoring;
 *                          verification could not be performed.
 *                          Operator fixes the listed cause(s) and
 *                          reruns. Do NOT escalate Option B from a
 *                          3 — that's the dispatch question 2
 *                          escalation path, and INCONCLUSIVE is not
 *                          the same signal as VERIFIED FAIL.
 *
 * Usage:
 *   SUPABASE_URL=... \
 *   SUPABASE_USER_JWT=... \
 *     npx tsx scripts/verify-tone-spec-empirical.ts
 *
 * The JWT must belong to a real Supabase user (the edge function
 * checks JWT and runs the rate-limit / budget guards). Easiest path:
 * sign in to the app, copy the access token from
 * `localStorage.getItem("sb-<project-ref>-auth-token")`.
 *
 * No CI integration. This script is operator-run. Its output is the
 * evidence Chau attaches to the PR before merging.
 */

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const SUPABASE_URL = process.env.SUPABASE_URL ?? process.env.VITE_SUPABASE_URL ?? "";
const SUPABASE_JWT = process.env.SUPABASE_USER_JWT ?? "";
const AUDIO_DIR = resolve(
  process.env.AUDIO_DIR ?? "public/audio/tones",
);

const PASS_THRESHOLD = 70;
const LOW_CONFIDENCE_THRESHOLD = 50;

type Bucket = "pass" | "low-confidence-pass" | "retry" | "unavailable";

function bucketFor(score: number): Exclude<Bucket, "unavailable"> {
  if (score >= PASS_THRESHOLD) return "pass";
  if (score >= LOW_CONFIDENCE_THRESHOLD) return "low-confidence-pass";
  return "retry";
}

function fatal(message: string): never {
  console.error(`[verify-tone-spec] ${message}`);
  process.exit(1);
}

interface CallResult {
  audioFile: string;
  targetSyllable: string;
  matched: boolean;
  score: number | null;
  bucket: Bucket;
  reason: string | null;
}

async function callOnce(args: {
  audioPath: string;
  audioFile: string;
  targetSyllable: string;
  matched: boolean;
}): Promise<CallResult> {
  const bytes = await readFile(args.audioPath);
  // The edge function expects WAV PCM 16k mono. mp3 will fail
  // `parseWavHeader`. Convert at runtime via ffmpeg for the
  // verification step. We shell out rather than ship a Node WAV
  // converter dependency.
  const wavBytes = await mp3ToWav16k(bytes);
  const blob = new Blob([wavBytes], { type: "audio/wav" });

  const formData = new FormData();
  formData.append("audio", blob, "ref.wav");
  formData.append("target_text", args.targetSyllable);
  formData.append("target_locale", "vi-VN");
  formData.append("context", "tone-drill");

  const url = `${SUPABASE_URL}/functions/v1/azure-phoneme`;
  const response = await fetch(url, {
    method: "POST",
    headers: { Authorization: `Bearer ${SUPABASE_JWT}` },
    body: formData,
  });

  if (!response.ok) {
    return {
      audioFile: args.audioFile,
      targetSyllable: args.targetSyllable,
      matched: args.matched,
      score: null,
      bucket: "unavailable",
      reason: `http_${response.status}`,
    };
  }

  const body = (await response.json()) as
    | { ok: true; score: number }
    | { ok: false; reason?: string };

  if (body.ok === false) {
    return {
      audioFile: args.audioFile,
      targetSyllable: args.targetSyllable,
      matched: args.matched,
      score: null,
      bucket: "unavailable",
      reason: body.reason ?? "azure-sentinel",
    };
  }

  return {
    audioFile: args.audioFile,
    targetSyllable: args.targetSyllable,
    matched: args.matched,
    score: body.score,
    bucket: bucketFor(body.score),
    reason: null,
  };
}

async function runFfmpeg(args: string[]): Promise<void> {
  const { spawn } = await import("node:child_process");
  return new Promise((resolveFn, reject) => {
    const ff = spawn("ffmpeg", args);
    ff.stderr.on("data", (chunk: Buffer) =>
      process.stderr.write(`[ffmpeg] ${chunk.toString()}`),
    );
    ff.on("error", reject);
    ff.on("close", (code) => {
      if (code === 0) {
        resolveFn();
      } else {
        reject(new Error(`ffmpeg exited with code ${code}`));
      }
    });
  });
}

/**
 * Convert mp3 bytes → WAV PCM 16k mono 16-bit, via ffmpeg with a temp
 * FILE output (NOT a pipe). With `pipe:1` output, ffmpeg cannot seek
 * back to patch the RIFF / data chunk size fields after the stream
 * closes — both end up as 0xFFFFFFFF placeholders. The edge function's
 * `parseWavHeader` then reads `dataSize = 0xFFFFFFFF`, computes
 * `durationSeconds = 0xFFFFFFFF / 32000 ≈ 134_217s`, and the
 * `audio_too_long` cap (60s) returns 413 — Azure is never called.
 *
 * Writing to a real file gives ffmpeg a seekable output; it patches
 * the header correctly on close, and downstream `parseWavHeader`
 * sees the true dataSize. Tradeoff: tmpdir IO per call. Negligible
 * for a 4-call operator verification.
 */
async function mp3ToWav16k(mp3: Uint8Array): Promise<Uint8Array> {
  const dir = await mkdtemp(join(tmpdir(), "tone-verify-"));
  const inPath = join(dir, "in.mp3");
  const outPath = join(dir, "out.wav");
  try {
    await writeFile(inPath, mp3);
    await runFfmpeg([
      "-hide_banner",
      "-loglevel", "error",
      "-y",
      "-i", inPath,
      "-ar", "16000",
      "-ac", "1",
      "-c:a", "pcm_s16le",
      outPath,
    ]);
    return new Uint8Array(await readFile(outPath));
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

function reportRow(r: CallResult): string {
  const score = r.score === null ? "—" : r.score.toFixed(1);
  const matchTag = r.matched ? "matched" : "mismatched";
  return `  ${r.audioFile.padEnd(10)} as ${r.targetSyllable.padEnd(4)} (${matchTag.padEnd(10)}) → ${r.bucket.padEnd(20)} score=${score} ${r.reason ?? ""}`;
}

async function main(): Promise<void> {
  if (!SUPABASE_URL) fatal("SUPABASE_URL env var is missing.");
  if (!SUPABASE_JWT) fatal("SUPABASE_USER_JWT env var is missing.");

  const maPath = resolve(AUDIO_DIR, "má.mp3");
  const mãPath = resolve(AUDIO_DIR, "mã.mp3");

  console.log(`[verify-tone-spec] running má vs mã empirical spec test`);
  console.log(`[verify-tone-spec] supabase: ${SUPABASE_URL}`);
  console.log(`[verify-tone-spec] audio:    ${AUDIO_DIR}`);
  console.log();

  const calls: CallResult[] = [];
  for (const args of [
    { audioPath: maPath, audioFile: "má.mp3", targetSyllable: "má", matched: true },
    { audioPath: maPath, audioFile: "má.mp3", targetSyllable: "mã", matched: false },
    { audioPath: mãPath, audioFile: "mã.mp3", targetSyllable: "mã", matched: true },
    { audioPath: mãPath, audioFile: "mã.mp3", targetSyllable: "má", matched: false },
  ]) {
    const result = await callOnce(args);
    calls.push(result);
    console.log(reportRow(result));
  }

  console.log();

  // Tristate classification per PRINCIPLES #7. The script must NOT
  // conflate "Azure failed" with "verification could not be performed."
  // Any `unavailable` outcome → INCONCLUSIVE (exit 3). Only when all
  // four calls produced a real score do we have grounds to declare
  // VERIFIED PASS (0) or VERIFIED FAIL (2).

  const inconclusive = calls.filter((c) => c.bucket === "unavailable");
  if (inconclusive.length > 0) {
    console.log("[verify-tone-spec] ⚠ INCONCLUSIVE — verification could not be performed.");
    console.log("[verify-tone-spec] Per PRINCIPLES #7, 'unavailable' is not 'Azure failed.' Fix the listed cause(s) and rerun.");
    console.log();
    console.log("[verify-tone-spec] Causes by call:");
    for (const c of inconclusive) {
      console.log(`  - ${c.audioFile} as ${c.targetSyllable}: ${c.reason}`);
    }
    process.exit(3);
  }

  const passed = (b: Bucket) => b === "pass" || b === "low-confidence-pass";
  const matchedOk = calls.filter((c) => c.matched).every((c) => passed(c.bucket));
  const mismatchedOk = calls.filter((c) => !c.matched).every((c) => c.bucket === "retry");

  if (matchedOk && mismatchedOk) {
    console.log("[verify-tone-spec] ✅ VERIFIED PASS — Azure distinguishes má/mã empirically.");
    console.log("[verify-tone-spec] Bar #2 closure is unblocked. Attach this output to the PR.");
    process.exit(0);
  }

  console.log("[verify-tone-spec] ❌ VERIFIED FAIL — Azure produced real scores but ordering is wrong.");
  console.log("[verify-tone-spec] Azure cannot empirically distinguish má (sắc) from mã (ngã).");
  console.log("[verify-tone-spec] Per dispatch question 2, do NOT ship Option A.");
  console.log("[verify-tone-spec] Escalate to a second design pass for Option B (Web Audio local pitch).");
  process.exit(2);
}

void main();
